import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for CoreFunction.functionID.
 * Since functionID is protected, we use a subclass to test it.
 */
public class CoreFunction_functionID_TriageGen1Test {

    private TestableCoreFunction coreFunction;
    private EvalContext mockContext;
    private JXPathContext mockJXPathContext;
    private Expression mockArg1;
    private NodePointer mockNodePointer;

    // Subclass to expose the protected method for testing
    private static class TestableCoreFunction extends CoreFunction {
        public TestableCoreFunction(int functionCode, Expression[] args) {
            super(functionCode, args);
        }

        @Override
        public Object functionID(EvalContext context) {
            return super.functionID(context);
        }
    }

    @Before
    public void setUp() {
        mockContext = mock(EvalContext.class);
        mockJXPathContext = mock(JXPathContext.class);
        mockArg1 = mock(Expression.class);
        mockNodePointer = mock(NodePointer.class);

        // Mocking the structure: context -> JXPathContext -> NodePointer
        when(mockContext.getJXPathContext()).thenReturn(mockJXPathContext);
        when(mockJXPathContext.getContextPointer()).thenReturn(mockNodePointer);

        // Initialize the function with one argument
        Expression[] args = new Expression[]{mockArg1};
        coreFunction = new TestableCoreFunction(1, args);
    }

    /**
     * Test successful retrieval of a node by ID.
     */
    @Test
    public void testFunctionID_Success() {
        String expectedId = "testId";
        Object expectedResult = new Object();

        // Mock the argument computation to return the ID string
        when(mockArg1.computeValue(mockContext)).thenReturn(expectedId);
        // Mock the pointer to return the expected object when called with the ID
        when(mockNodePointer.getPointerByID(mockJXPathContext, expectedId)).thenReturn(expectedResult);

        Object result = coreFunction.functionID(mockContext);

        assertNotNull(result);
        assertEquals(expectedResult, result);
    }

    /**
     * Test when the argument returns an object that is not a string (testing InfoSetUtil.stringValue behavior).
     * Note: InfoSetUtil.stringValue typically converts the object to a string.
     */
    @Test
    public void testFunctionID_NonStringArgument() {
        Integer idAsInt = 123;
        String expectedIdString = "123";
        Object expectedResult = new Object();

        when(mockArg1.computeValue(mockContext)).thenReturn(idAsInt);
        when(mockNodePointer.getPointerByID(mockJXPathContext, expectedIdString)).thenReturn(expectedResult);

        Object result = coreFunction.functionID(mockContext);

        assertEquals(expectedResult, result);
    }

    /**
     * Test behavior when the pointer returns null for the given ID.
     */
    @Test
    public void testFunctionID_ReturnsNull() {
        String id = "nonExistent";
        when(mockArg1.computeValue(mockContext)).thenReturn(id);
        when(mockNodePointer.getPointerByID(mockJXPathContext, id)).thenReturn(null);

        Object result = coreFunction.functionID(mockContext);

        assertEquals(null, result);
    }

    /**
     * Test that assertArgCount(1) triggers an error if arguments are incorrect.
     * Note: This depends on the implementation of assertArgCount in the base class.
     * Usually, it throws an IllegalArgumentException or similar.
     */
    @Test(expected = RuntimeException.class)
    public void testFunctionID_WrongArgumentCount() {
        // Create a function with 0 arguments instead of 1
        Expression[] emptyArgs = new Expression[0];
        TestableCoreFunction badFunction = new TestableCoreFunction(1, emptyArgs);

        // This should trigger assertArgCount(1) failure
        badFunction.functionID(mockContext);
    }
}
